import{_ as a,o as s,c as t,ag as i}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"API HTTP","description":"","frontmatter":{},"headers":[],"relativePath":"es/nay-lib/api.md","filePath":"es/nay-lib/api.md"}'),d={name:"es/nay-lib/api.md"};function o(n,e,l,r,c,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="api-http" tabindex="-1">API HTTP <a class="header-anchor" href="#api-http" aria-label="Permalink to &quot;API HTTP&quot;">​</a></h1><p>Los scripts y las webs (paneles de control, bots de Discord, tiendas) pueden leer y modificar el servidor mediante una API JSON servida por FXServer en el puerto del juego:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;server ip&gt;:&lt;port&gt;/&lt;resource&gt;/v1/&lt;route&gt;</span></span></code></pre></div><h2 id="activarla" tabindex="-1">Activarla <a class="header-anchor" href="#activarla" aria-label="Permalink to &quot;Activarla&quot;">​</a></h2><p>La API está <strong>desactivada por defecto</strong>. Actívala en <code>/nay</code>, en la página <strong>Nayretis</strong>: <strong>API HTTP</strong> (<code>ApiEnabled</code>). Mientras está desactivada, todas las rutas responden <code>503 api_disabled</code>. <strong>Tamaño máximo de solicitud (KB)</strong> (<code>ApiMaxBodyKb</code>) limita el cuerpo de las solicitudes (1024 KB por defecto).</p><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h2><p>Crea los tokens en la pestaña <strong>API</strong> de <code>/nay</code> (el token se muestra una sola vez: cópialo en ese momento) o desde la consola del servidor:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_api_token create &lt;label&gt; &lt;scope...&gt;</span></span>
<span class="line"><span>nay_api_token list</span></span>
<span class="line"><span>nay_api_token revoke &lt;id&gt;</span></span></code></pre></div><p>Un token tiene la forma <code>nay_&lt;id&gt;_&lt;secret&gt;</code>. Solo se guarda su hash SHA-256. Cada token tiene sus scopes, direcciones permitidas opcionales (IPv4, IPv6 o rangos CIDR), un límite de solicitudes por minuto y una caducidad opcional.</p><p>Los scopes tienen la forma <code>&lt;resource&gt;.&lt;scope&gt;</code>, con comodines: <code>nay_car_wash.*</code> da todas las rutas de un script, <code>*</code> lo da todo. Cada script indica sus rutas y scopes en su propia página, por ejemplo <a href="/es/car-wash/api">Car Wash</a>.</p><h2 id="solicitudes" tabindex="-1">Solicitudes <a class="header-anchor" href="#solicitudes" aria-label="Permalink to &quot;Solicitudes&quot;">​</a></h2><ul><li>Envía <code>Authorization: Bearer &lt;token&gt;</code>.</li><li>Los cuerpos son JSON (<code>Content-Type: application/json</code>) con un <code>Content-Length</code>. Los cuerpos fragmentados (chunked) se rechazan.</li><li>Tras 10 autenticaciones fallidas en un minuto, las solicitudes sin token válido desde esa dirección se rechazan durante 5 minutos. Los tokens válidos siguen funcionando.</li><li>Detrás de un proxy inverso, define <code>nay:apiTrustedProxies</code> (consulta <a href="#https">HTTPS</a>). Si no, todos los clientes comparten la dirección del proxy.</li></ul><p>Cada respuesta es JSON con una cabecera <code>X-Request-Id</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;forbidden&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;This token does not allow this route&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;details&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { } } }</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Estado</th><th>Código</th><th>Significado</th></tr></thead><tbody><tr><td>400</td><td><code>unexpected_body</code>, <code>invalid_json</code>, <code>invalid_request</code></td><td>Cuerpo enviado a una ruta sin cuerpo, cuerpo que no es JSON válido, o <code>Content-Length</code> mal formado.</td></tr><tr><td>401</td><td><code>unauthorized</code></td><td>Token ausente, desconocido, revocado o caducado.</td></tr><tr><td>403</td><td><code>forbidden</code>, <code>ip_not_allowed</code></td><td>El token no tiene el scope, o la dirección no está permitida para él.</td></tr><tr><td>404 / 405</td><td><code>not_found</code>, <code>method_not_allowed</code></td><td>Ruta desconocida, o método incorrecto en una ruta conocida.</td></tr><tr><td>411</td><td><code>length_required</code></td><td>Cualquier <code>Transfer-Encoding</code> (cuerpo fragmentado).</td></tr><tr><td>413</td><td><code>payload_too_large</code></td><td>Cuerpo por encima de <code>ApiMaxBodyKb</code>. Un <code>Content-Length</code> anunciado de más de 10 MB se rechaza antes de leer el cuerpo.</td></tr><tr><td>415</td><td><code>unsupported_media_type</code></td><td>Cuerpo que no es <code>application/json</code>.</td></tr><tr><td>422</td><td><code>invalid_request</code>, <code>unknown_parameter</code>, <code>invalid_value</code></td><td>Parámetro, query o cuerpo que no pasa la validación (<code>details.path</code> y <code>details.reason</code>).</td></tr><tr><td>429</td><td><code>rate_limited</code>, <code>too_many_failures</code></td><td>Token por encima de su límite por minuto, o dirección bloqueada. Consulta <code>Retry-After</code>.</td></tr><tr><td>500</td><td><code>internal_error</code></td><td>La ruta ha fallado. Consulta la consola del servidor.</td></tr><tr><td>503</td><td><code>api_disabled</code>, <code>not_ready</code></td><td>API desactivada, o recurso todavía arrancando (<code>Retry-After</code>).</td></tr><tr><td>504</td><td><code>timeout</code></td><td>La ruta no respondió en 10 segundos. Sigue ejecutándose: un cambio puede aplicarse aun después del 504, así que vuelve a leer el estado antes de reintentar.</td></tr></tbody></table><h2 id="rutas-de-nay-lib" tabindex="-1">Rutas de nay_lib <a class="header-anchor" href="#rutas-de-nay-lib" aria-label="Permalink to &quot;Rutas de nay_lib&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Método</th><th>Ruta</th><th>Scope</th><th>Datos</th></tr></thead><tbody><tr><td>GET</td><td><code>/nay_lib/v1/status</code></td><td><code>nay.status</code></td><td>Nombre del servidor, jugadores, máximo de jugadores, framework, inventario, target, recursos Nayretis y sus versiones.</td></tr><tr><td>GET</td><td><code>/nay_lib/v1/players</code></td><td><code>nay.players</code></td><td>Jugadores conectados: id, nombre, personaje, identificador, trabajo.</td></tr><tr><td>GET</td><td><code>/nay_lib/v1/settings/:resource</code></td><td><code>nay.settings</code> más <code>&lt;resource&gt;.config</code> o <code>nay.config</code></td><td>Ajustes de un script con sus valores.</td></tr><tr><td>PUT</td><td><code>/nay_lib/v1/settings/:resource/:key</code></td><td>igual</td><td>Cambia un ajuste. Cuerpo <code>{ &quot;value&quot;: ... }</code>.</td></tr><tr><td>DELETE</td><td><code>/nay_lib/v1/settings/:resource/:key</code></td><td>igual</td><td>Restablece un ajuste a su valor por defecto.</td></tr><tr><td>GET</td><td><code>/nay_lib/v1/audit</code></td><td><code>nay.audit</code></td><td>Registro de auditoría, 50 entradas por página. Query <code>resource</code>, <code>action</code>, <code>actor</code>, <code>from</code> y <code>to</code> (segundos Unix), <code>page</code>.</td></tr></tbody></table><p>Cada llamada que cambia algo se anota en el <a href="/es/nay-lib/audit">registro de auditoría</a> (<code>api.call</code>, autor <code>api:&lt;token label&gt;</code>).</p><h2 id="https" tabindex="-1">HTTPS <a class="header-anchor" href="#https" aria-label="Permalink to &quot;HTTPS&quot;">​</a></h2><p>FXServer solo habla HTTP sin cifrar: cualquiera en el camino puede leer un token enviado así. Coloca delante de la API un proxy inverso con certificado y expón solo las rutas que uses. Después indica a <code>nay_lib</code> en qué proxies confiar, para que las direcciones permitidas y los límites de solicitudes se apliquen a la dirección real del cliente, tomada de <code>X-Forwarded-For</code>:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set nay:apiTrustedProxies &quot;127.0.0.1&quot;</span></span></code></pre></div><p>El valor es una lista de direcciones o rangos CIDR separados por comas.</p><p>nginx:</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssl;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api.example.com;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	ssl_certificate </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/etc/letsencrypt/live/api.example.com/fullchain.pem;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	ssl_certificate_key </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/etc/letsencrypt/live/api.example.com/privkey.pem;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	location</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ~</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;"> ^/(nay_lib|nay_car_wash)/v1/ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:30120;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-For $remote_addr;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">		client_max_body_size </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1m</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Caddy (certificado obtenido automáticamente):</p><div class="language-caddy vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">caddy</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api.example.com {</span></span>
<span class="line"><span>	@nayretis path_regexp ^/(nay_lib|nay_car_wash)/v1/</span></span>
<span class="line"><span>	reverse_proxy @nayretis 127.0.0.1:30120</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,26)])])}const k=a(d,[["render",o]]);export{u as __pageData,k as default};
